param([string]$Exe="$PSScriptRoot\..\artifacts\recovery-2026-10-26\final-r4\mdcard.exe",[int[]]$MiB=@(1,8,16),[ValidateSet('On','Off','Both')][string]$Recovery='Both',[string]$OutputDirectory='')
