$output=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path -LiteralPath $output){throw 'Use a new isolated output directory'};New-Item -ItemType Directory -Force $output|Out-Null
$utf8=[Text.UTF8Encoding]::new($false);$variables=@('MDCARD_UI_REPORT','MDCARD_PERFORMANCE_REPORT','MDCARD_SEARCH_REPORT','MDCARD_RECOVERY_DIR','MDCARD_READING_STATE_PATH','MDCARD_RENDERER_DIR','MDCARD_RICH_REPORT','MDCARD_STRUCTURE_REPORT');$old=@{};foreach($v in $variables){$old[$v]=[Environment]::GetEnvironmentVariable($v,'Process');[Environment]::SetEnvironmentVariable($v,$null,'Process')}
