function Click([float]$X,[float]$Y){$r=Bounds;$s=[MdcardUi]::GetDpiForWindow($script:app.MainWindowHandle)/96.;[void][MdcardUi]::SetCursorPos($r.Left+[int]($X*$s),$r.Top+[int]($Y*$s));Start-Sleep -Milliseconds 80;[MdcardUi]::mouse_event(2,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 80;[MdcardUi]::mouse_event(4,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 250}
function Control([string]$Name){$r=Report;$c=$r.controls|Where-Object name -EQ $Name|Select-Object -First 1;if(!$c){throw "Missing control $Name"};Click (($c.rect[0]+$c.rect[2])/2) (($c.rect[1]+$c.rect[3])/2)}
