try{
foreach($enabled in $(if($Recovery-eq'Both'){@($false,$true)}else{@($Recovery-eq'On')})) {foreach($sizeMiB in $MiB){
$label="$sizeMiB-$(if($enabled){'on'}else{'off'})";$dir=Join-Path $output $label;New-Item -ItemType Directory -Force $dir|Out-Null
$settings=Join-Path $dir 'settings.json';@{language='en';appearance='Light';gpu_acceleration=$true;reduce_motion=$true;font_size=15;autosave=$false;recovery=$enabled}|ConvertTo-Json|Set-Content -LiteralPath $settings -Encoding utf8
$env:MDCARD_UI_REPORT=Join-Path $dir 'ui.json';$env:MDCARD_PERFORMANCE_REPORT=Join-Path $dir 'performance.json';$env:MDCARD_RECOVERY_DIR=Join-Path $dir 'state';$env:MDCARD_READING_STATE_PATH=Join-Path $dir 'reading.json'
$p=Join-Path $dir 'manuscript.md';$line="A measured manuscript paragraph with plain ASCII text for consistent byte counts. `n";$length=$sizeMiB*1MB-256;$text=($line*[int][Math]::Ceiling($length/$line.Length)).Substring(0,$length);[IO.File]::WriteAllText($p,$text,$utf8);$text=$null
$stagePath=Join-Path $dir 'stage.txt';$stopPath=Join-Path $dir 'stop';$samplePath=Join-Path $dir 'samples.jsonl';[IO.File]::WriteAllText($stagePath,'launch')
