foreach($name in @('MDCARD_SEARCH_REPORT','MDCARD_RICH_REPORT','MDCARD_STRUCTURE_REPORT','MDCARD_READING_REPORT','MDCARD_READING_GEOMETRY_REPORT','MDCARD_UI_MATRIX_REPORT','MDCARD_AUTO_QUIT_SECONDS','MDCARD_SCREENSHOT','MDCARD_PERFORMANCE_CONTINUOUS')){[void]$launch.Environment.Remove($name)}
$launch.Environment['MDCARD_SETTINGS_PATH']=$settings;$launch.Environment['MDCARD_RENDERER_REPORT']=Join-Path $dir 'renderer.json';$launch.ArgumentList.Add($p)
@{search_report_present=$launch.Environment.ContainsKey('MDCARD_SEARCH_REPORT');rich_report_present=$launch.Environment.ContainsKey('MDCARD_RICH_REPORT');structure_report_present=$launch.Environment.ContainsKey('MDCARD_STRUCTURE_REPORT');diagnostic_keys=@($launch.Environment.Keys|Where-Object {$_-match'^MDCARD_.*REPORT$'}|Sort-Object);ui_report=$launch.Environment['MDCARD_UI_REPORT'];performance_report=$launch.Environment['MDCARD_PERFORMANCE_REPORT'];original_autosave=$false;recovery=$enabled}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $dir 'launch-environment.json') -Encoding utf8
$script:app=[Diagnostics.Process]::Start($launch)
$job=Start-Job -ArgumentList $script:app.Id,$samplePath,$stagePath,$stopPath,$env:MDCARD_UI_REPORT,(Join-Path $PSScriptRoot 'recovery-json.ps1') -ScriptBlock {param($TargetPid,$SamplePath,$StagePath,$StopPath,$UiPath,$HelperPath);. $HelperPath;$process=Get-Process -Id $TargetPid;$writer=[IO.StreamWriter]::new($SamplePath,$false);try{while(!(Test-Path -LiteralPath $StopPath)){$process.Refresh();if($process.HasExited){break};$stage=try{[IO.File]::ReadAllText($StagePath)}catch{'transition'};$r=try{ReadJsonStable $UiPath @('recovery') 1}catch{$null};$sample=@{writers=if($r){@(@($r.recovery.main,$r.recovery.secondary)|Where-Object working).Count}else{$null};checkpoint=$r.recovery.main;at=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();stage=$stage;working_set=$process.WorkingSet64;private_bytes=$process.PrivateMemorySize64;peak_working_set=$process.PeakWorkingSet64;peak_pagefile_bytes=$process.PeakPagedMemorySize64};$writer.WriteLine(($sample|ConvertTo-Json -Compress));$writer.Flush();Start-Sleep -Milliseconds 50}}finally{$writer.Dispose()}}
Start-Sleep -Seconds 3;$script:app.Refresh();[void][MdcardUi]::MoveWindow($script:app.MainWindowHandle,50,50,1550,1025,$true);[void][MdcardUi]::SetWindowPos($script:app.MainWindowHandle,[IntPtr]::new(-1),0,0,0,0,0x43);[void][MdcardUi]::SetForegroundWindow($script:app.MainWindowHandle);Start-Sleep -Milliseconds 350;Click 500 27;[void][MdcardUi]::SetWindowPos($script:app.MainWindowHandle,[IntPtr]::new(-2),0,0,0,0,0x43)
$details=[Collections.Generic.List[object]]::new();Stage 'opened-default';$r=Report;if($r.autosave.enabled-or$r.recovery.enabled-ne$enabled){throw 'Isolated preferences were not applied'};Control 'Write';Stage 'write';Control 'main-source-editor';Keys '^{END}';Set-Clipboard -Value "`nRecovery measurement edit.";Keys '^v';Stage 'first-edit';Set-Clipboard -Value 'x'
for($i=0;$i-lt120;$i++){[Windows.Forms.SendKeys]::SendWait('^v');Start-Sleep -Milliseconds 80;if($i%20-eq19){Stage "continuous-$($i+1)"};if($i-eq45){[MdcardUi]::mouse_event(0x800,0,0,120,[UIntPtr]::Zero)};if($i-eq70){Control 'Read';Stage 'read';Control 'Write';Control 'main-source-editor';Keys '^{END}';Stage 'write-return'}}
Stage 'typing-ended';if($enabled){WaitUntil {$r=Report;$r.recovery.main.current_version-and!$r.recovery.main.working} 'Checkpoint did not commit'};Start-Sleep -Seconds 2;Stage 'settled';Keys '^s';WaitUntil {!(Report).dirty-and!(Report).autosave.main.saving} 'Save did not finish';if(![IO.File]::ReadAllText($p).Contains('Recovery measurement edit.')){throw 'Manual save lost edit marker'};Stage 'manual-saved';Start-Sleep -Seconds 2;Stage 'saved-settled';Shot $label
$report=ReadJsonStable $env:MDCARD_PERFORMANCE_REPORT @('update_cpu_ms');$details.ToArray()|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $dir 'stages.json') -Encoding utf8
[IO.File]::WriteAllText($stopPath,'stop');Wait-Job $job -Timeout 5|Out-Null;Receive-Job $job;Remove-Job $job;$job=$null;$script:app.Refresh();$all+=@{label=$label;mib=$sizeMiB;recovery=$enabled;source_bytes=$length;exe_sha256=(Get-FileHash $Exe).Hash;peak_working_set=$script:app.PeakWorkingSet64;private_bytes_end=$script:app.PrivateMemorySize64;stages=$details.ToArray();update_cpu_ms=$report.update_cpu_ms;input_cpu_ms=$report.input_event_to_update_finish_ms};$script:app.Kill();$script:app.WaitForExit()
}}
$all|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $output 'measurements.json') -Encoding utf8
@{passed=$true;exe_sha256=(Get-FileHash $Exe).Hash;date=[DateTimeOffset]::Now.ToString('o');diagnostics=@('UI metadata','performance');sampler_ms=50;scenarios=$all.Count}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $output 'result.json') -Encoding utf8
}catch{$_|Out-String|Set-Content -LiteralPath (Join-Path $output 'failure.txt');throw}finally{if($job){Stop-Job $job;Remove-Job $job};if($script:app-and!$script:app.HasExited){$script:app.Kill()};foreach($v in $variables){[Environment]::SetEnvironmentVariable($v,$old[$v],'Process')};if($null-ne$clipboard){[Windows.Forms.Clipboard]::SetDataObject($clipboard,$true)}}
Write-Output $output
